// Block (composition) — a floating, iOS-style bottom navigation bar.
// Contract: docs/rules/block-contract.md. Arranges only: Card supplies the
// themed surface — `size="small" variant="raised"` gives the compact inset plus the elevation that
// makes the bar read as floating. NavItem (orientation="vertical")
// supplies each icon+label item and its look, Grid lays them out in equal columns. The
// Block owns no look and mints no tokens — its own CSS only fixes the bar to the
// bottom-center of the viewport. Posture: self-contained floating chrome.
import type { ReactNode, Ref } from "react";
import { Card } from "../components/Card";
import { useScrollClearance } from "../components/useScrollClearance";
import { NavItem } from "../components/NavItem";
import { Grid } from "../layouts/Grid";
import "./BottomNav.css";

export interface BottomNavItemBase {
  /** Visible label under the icon. */
  label: string;
  /** Item icon (sized to the icon slot; inherits the item's text color). */
  icon: ReactNode;
  /** Marks the active tab — applies aria-current + the selected highlight. */
  isCurrent?: boolean;
}

/** Link or button, never both — mirrors NavItem's own mode union so the either/or the JSDoc
    always claimed is enforced at the data layer, not silently resolved in favour of `href`. */
export type BottomNavItem = BottomNavItemBase &
  (
    | {
        /** Destination. Present → renders a link. */
        href: string;
        onPress?: never;
      }
    | {
        href?: never;
        /** Press handler — button mode (no `href`). */
        onPress?: () => void;
      }
  );

export interface BottomNavProps {
  /** Navigation destinations — intended for 3–5 top-level sections. */
  items: BottomNavItem[];
  /** Accessible name for the navigation landmark. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function BottomNav({
  items,
  "aria-label": ariaLabel = "Primary",
  className,
  ref,
}: BottomNavProps) {
  // The bar covers the bottom of the page, so the document keeps focus clear of it (WCAG 2.4.11).
  // Room after the page's last row is the page's own: AppShell keeps it for its `bottomNav` slot.
  const clearRef = useScrollClearance("end", ref);
  return (
    <nav
      ref={clearRef}
      aria-label={ariaLabel}
      className={className ? `sd-bottomnav ${className}` : "sd-bottomnav"}
    >
      {/* `raised` because this bar genuinely floats — it is `position: fixed` on the sticky layer,
          over page content. The elevation belongs to the surface that wraps the items (§6: the
          floating surface belongs to whatever WRAPS it), not to this Block, which owns no look.
          `small` keeps a compact bar rather than using the roomier card tier. */}
      <Card size="small" variant="raised" className="sd-bottomnav__bar">
        {/* One equal column per tab, so every item is as wide as the widest label and the bar reads
            as a row of peers rather than a run of words. The items overlap by a -4 gap, so
            their hit areas meet and the bar reads as one strip. */}
        <Grid columns={items.length} gap="none" className="sd-bottomnav__items">
          {items.map((item, index) =>
            item.href != null ? (
              <NavItem
                key={`${item.label}-${index}`}
                orientation="vertical"
                icon={item.icon}
                isCurrent={item.isCurrent}
                href={item.href}
                className="sd-bottomnav__item"
              >
                {item.label}
              </NavItem>
            ) : (
              <NavItem
                key={item.label}
                orientation="vertical"
                icon={item.icon}
                isCurrent={item.isCurrent}
                onPress={item.onPress}
                className="sd-bottomnav__item"
              >
                {item.label}
              </NavItem>
            ),
          )}
        </Grid>
      </Card>
    </nav>
  );
}

/* BottomNav.css — .sd-bottomnav (Block)
   Arrangement only: pin the bar to the bottom-center of the viewport. All look
   (surface, radius, shadow) is owned by the composed Card (size=small variant=raised); each item's look by
   NavItem. References Sys layout scales only; defines no tokens. */
.sd-bottomnav {
  position: fixed;
  inset-inline: 0;
  inset-block-end: var(--sd-overlay-margin-medium);
  display: flex;
  justify-content: center;
  z-index: var(--sd-layer-sticky);
  /* Let clicks fall through the transparent gutter beside the bar; the bar itself
     re-enables hit-testing below. */
  pointer-events: none;
}

.sd-bottomnav__bar {
  pointer-events: auto;
}

/* A -4 gap between items: a grid gap cannot be negative, so each item gives
   back half of `space.2x-small` on both inline sides. */
.sd-bottomnav__item {
  margin-inline: calc(var(--sd-space-2x-small) / -2);
}
